# -*- coding: utf-8 -*-
"""第四批：场景/选型型答案页（24 篇）"""
NEW = [
 {'slug': 'router-bit-for-mdf', 'q': 'What router bit should I use for MDF?', 'a': 'Straight carbide bits with 2 flutes. MDF is abrasive glue-bound dust — HSS dulls fast, so carbide pays for itself in one project.', 'body': '<table><tr><th>Job in MDF</th><th>Bit</th><th>Why</th></tr><tr><td>Grooves and dados</td><td>Straight bit, 2 flute, carbide</td><td>Clears dust, holds size</td></tr><tr><td>Edge profiling</td><td>Round-over or chamfer, carbide, bearing guided</td><td>Bearing follows a template</td></tr><tr><td>Rabbets</td><td>Straight or rebate bit with bearing</td><td>Controlled depth</td></tr></table><p><b>Settings that matter:</b> MDF burns at low feed. Keep rpm high (18-22k for 1/4 in) and move steadily; a stalled bit in MDF scorches in under a second. Wear a respirator — the dust is the real hazard, not the cut.</p>', 'answer_short': 'Use a 2-flute carbide straight bit for grooves and a bearing-guided round-over for edges. MDF is abrasive, so HSS dulls fast; carbide lasts far longer.', 'links': ['RB-12W', 'RB-15W']},
 {'slug': 'router-bit-for-melamine', 'q': 'Why does melamine chip when I rout it and which bit stops it?', 'a': 'Chip-out comes from the cut geometry, not the rpm. Use a down-cut or compression bit, and score the cut line if the edge must be perfect.', 'body': '<table><tr><th>Bit</th><th>Where it works</th><th>Trade-off</th></tr><tr><td>Down-cut spiral</td><td>Top face stays clean</td><td>Chip evacuation is poor, slow feed needed</td></tr><tr><td>Up-cut spiral</td><td>Bottom face clean</td><td>Tears the top face</td></tr><tr><td>Compression</td><td>Both faces clean on 18 mm board</td><td>Needs the right depth of cut</td></tr><tr><td>Straight 2-flute</td><td>Cheap work, tear-out accepted</td><td>Chips the top edge</td></tr></table><p><b>Practical fix:</b> score the line with a knife, or put masking tape over the cut before routing. A compression bit only works when the up-cut and down-cut halves both engage the board.</p>', 'answer_short': 'Use a down-cut spiral to protect the top face, or a compression bit on 18 mm board to protect both faces. Scoring the line or taping it also stops chip-out.', 'links': ['RB-12Z', 'RB-15Z']},
 {'slug': 'router-bit-plywood-blowout', 'q': 'How do I stop tear-out when routing plywood?', 'a': 'Slow the feed at the exit corner, use a down-cut bit on the visible face, and take a light climb cut on the last pass.', 'body': '<table><tr><th>Cause</th><th>Fix</th></tr><tr><td>Tear-out at the exit corner</td><td>Climb cut the last 20 mm, very light</td></tr><tr><td>Fuzzy edges on cross grain</td><td>Down-cut spiral on the top face</td></tr><tr><td>Blowout on the bottom face</td><td>Sacrificial backer board</td></tr><tr><td>Whole veneer layer lifts</td><td>Bit is dull, or feed too fast</td></tr></table><p><b>Why plywood is worse than solid wood:</b> each veneer layer has grain running a different direction, so one side of the cut is always against the grain. A backer board and a sharp bit do more than any change in rpm.</p>', 'answer_short': 'Use a down-cut bit on the visible face, a backer board underneath, and a light climb cut on the last pass at the exit corner. Plywood tears out because each veneer layer runs a different direction.', 'links': ['RB-12Z8', 'RB-15Z8']},
 {'slug': 'how-long-do-router-bits-last', 'q': 'How long does a router bit set actually last?', 'a': 'A hobby shop gets 2-3 years from a carbide set. A production shop running daily gets 3-9 months from the same set. Heat is what kills them, not hours.', 'body': '<table><tr><th>Use</th><th>Realistic life</th><th>What kills it</th></tr><tr><td>Weekend hobby, softwood</td><td>2-3 years</td><td>Resin build-up</td></tr><tr><td>Daily cabinet work</td><td>6-12 months</td><td>Heat from dull edges</td></tr><tr><td>MDF or particleboard daily</td><td>3-6 months</td><td>Abrasive glue</td></tr><tr><td>Any bit run too fast</td><td>One job</td><td>Burned carbide</td></tr></table><p><b>Three habits that double life:</b> clean resin off with oven cleaner rather than scraping, never let the bit sit in the collet dirty, and drop rpm for large diameter bits. A 3 in panel bit at 24,000 rpm is being destroyed even while it cuts.</p>', 'answer_short': "Two to three years for a hobby shop, three to nine months for daily production. Heat and resin build-up end a bit's life long before the carbide wears out.", 'links': ['RB-12W', 'RB-15HW']},
 {'slug': 'do-cheap-router-bit-sets-work', 'q': 'Are cheap router bit sets good enough?', 'a': 'For softwood and occasional use, yes. For hardwood, MDF, or anything you sell, no — the bearings and the carbide grade are where the money went.', 'body': '<table><tr><th>Part</th><th>Cheap set</th><th>What it costs you</th></tr><tr><td>Carbide grade</td><td>Thin, micro-grain not specified</td><td>Dulls in one MDF project</td></tr><tr><td>Bearings</td><td>Loose, no seal</td><td>Bearing seizes, burns the profile</td></tr><tr><td>Shank grind</td><td>Out of tolerance</td><td>Slips in the collet</td></tr><tr><td>Balance</td><td>Poor at high rpm</td><td>Vibration, chatter, poor finish</td></tr></table><p><b>How to tell before buying:</b> a set that lists the carbide grade and bearing spec is usually serious. A set that lists only piece count is not.</p>', 'answer_short': 'Cheap sets are fine in softwood for occasional use. They fail on hardwood and MDF because the carbide grade and bearings are where the cost was cut.', 'links': ['RB-12P', 'RB-15P']},
 {'slug': 'router-bit-storage-and-rust', 'q': 'How should I store router bits so they do not rust or chip?', 'a': 'Wooden case, stood upright, with a silica pack. Never let bits touch each other — carbide chips against carbide.', 'body': '<table><tr><th>Problem</th><th>Cause</th><th>Fix</th></tr><tr><td>Rust spots on shanks</td><td>Humidity over 60%</td><td>Silica pack in the case, oil the shank lightly</td></tr><tr><td>Chipped edges</td><td>Bits rattling together in a drawer</td><td>Individual slots, wooden case</td></tr><tr><td>Stuck bearings</td><td>Resin dried in the bearing</td><td>Clean after every session</td></tr><tr><td>Bent shanks</td><td>Dropped</td><td>Treat as scrap; a bent shank cannot be fixed</td></tr></table><p><b>A workshop in a humid climate:</b> a closed wooden case with a silica pack holds up far better than an open rack, and it protects the edges during transport.</p>', 'answer_short': 'Store bits upright in a wooden case with a silica pack, each in its own slot. Carbide chips against carbide, so bits must not rattle together.', 'links': ['RB-12W', 'RB-15W']},
 {'slug': 'step-drill-bit-vs-hole-saw', 'q': 'Step drill or hole saw for sheet metal?', 'a': 'Step drill for holes up to about 35 mm in sheet under 4 mm thick. Hole saw above that, or for thicker plate.', 'body': '<table><tr><th></th><th>Step drill</th><th>Hole saw</th></tr><tr><td>Best thickness</td><td>0.5-4 mm sheet</td><td>Any, but 2 mm+ is comfortable</td></tr><tr><td>Hole size</td><td>Up to about 35 mm</td><td>16 mm to 150 mm</td></tr><tr><td>Edge quality</td><td>Clean, deburred by the next step</td><td>Rougher, needs filing</td></tr><tr><td>Cost per hole</td><td>One tool, many sizes</td><td>One saw per size</td></tr><tr><td>Failure mode</td><td>Snaps if you lever it</td><td>Teeth strip in stainless</td></tr></table><p><b>Rule of thumb:</b> electrical panels, enclosures and conduit work belong to the step drill. Door locks, pipe and duct work belong to the hole saw.</p>', 'answer_short': 'Step drill for sheet metal under 4 mm and holes up to 35 mm. Hole saw for larger holes, thicker plate, wood and pipe.', 'links': ['HS-8']},
 {'slug': 'forstner-vs-hole-saw', 'q': 'Forstner bit or hole saw for a clean, flat-bottomed hole?', 'a': 'Forstner. It cuts a flat bottom and a clean rim; a hole saw leaves a plug and a rougher edge.', 'body': '<table><tr><th></th><th>Forstner</th><th>Hole saw</th></tr><tr><td>Hole bottom</td><td>Flat, controlled depth</td><td>Through-hole only</td></tr><tr><td>Rim quality</td><td>Clean, splinter-free</td><td>Rougher</td></tr><tr><td>Depth</td><td>Any, up to the shank</td><td>Limited by the barrel</td></tr><tr><td>Diameter range</td><td>10-50 mm typical</td><td>16-150 mm</td></tr><tr><td>Overlapping holes</td><td>Easy, centre point guides</td><td>Difficult</td></tr></table><p><b>Where the hole saw wins:</b> through-holes in doors for locksets, pipe penetrations, and anything above 50 mm. The Forstner is the hinge-cup and dowel tool.</p>', 'answer_short': 'Forstner for flat-bottomed holes, clean rims and controlled depth. Hole saw for through-holes, larger diameters, pipe and door locks.', 'links': ['HS-8']},
 {'slug': 'hole-saw-arbor-sizes', 'q': 'Which arbor fits my hole saw?', 'a': 'Match the arbor thread to the saw: 1/2-20 for most small saws, 5/8-18 for larger ones. The pilot drill diameter matters too.', 'body': '<table><tr><th>Saw diameter</th><th>Typical arbor thread</th><th>Pilot drill</th></tr><tr><td>14-30 mm</td><td>1/2-20</td><td>1/4 in</td></tr><tr><td>32-60 mm</td><td>5/8-18</td><td>1/4 in</td></tr><tr><td>68 mm and up</td><td>5/8-18 heavy duty</td><td>1/4 in, sometimes 5/16 in</td></tr></table><p><b>Two checks before you buy:</b> the thread on the saw, and whether the arbor has a collar stop. A hex shank arbor that fits a 10 mm chuck will not fit a 3/8 in chuck.</p>', 'answer_short': 'Match the arbor thread to the saw — 1/2-20 for most small saws, 5/8-18 for larger. Check the pilot drill size and the chuck capacity too.', 'links': ['HS-8']},
 {'slug': 'hole-saw-for-stainless-steel', 'q': 'Can a bi-metal hole saw cut stainless steel?', 'a': 'Yes, at low rpm with constant cutting fluid and light pressure — but expect one or two holes per saw, not fifty.', 'body': '<table><tr><th>Material</th><th>RPM (25 mm saw)</th><th>Fluid</th><th>Life</th></tr><tr><td>Mild steel 2 mm</td><td>350-500</td><td>Cutting oil</td><td>30-80 holes</td></tr><tr><td>Stainless 304, 1 mm</td><td>150-250</td><td>Constant flood</td><td>1-5 holes</td></tr><tr><td>Aluminium</td><td>600-900</td><td>Wax or none</td><td>50+ holes</td></tr><tr><td>Wood</td><td>1,500-2,500</td><td>None</td><td>100+ holes</td></tr></table><p><b>The mistake that kills saws:</b> running dry and fast in stainless. The teeth work-harden the steel the moment they rub instead of cut, and then nothing will get through.</p>', 'answer_short': 'Yes, but slowly: low rpm, constant cutting fluid, light pressure. Expect one to five holes in stainless rather than the dozens you get in mild steel.', 'links': ['HS-8']},
 {'slug': 'drill-bit-for-stainless-steel', 'q': 'Which drill bit actually works on stainless steel?', 'a': 'M35 cobalt with a 135-degree split point, run at about a third of the speed you would use in mild steel, with cutting fluid.', 'body': '<table><tr><th>Bit</th><th>In stainless</th><th>Verdict</th></tr><tr><td>HSS black oxide</td><td>Burns out fast</td><td>Avoid</td></tr><tr><td>HSS-Co M35 (5% Co)</td><td>Works with fluid and low rpm</td><td>Standard choice</td></tr><tr><td>HSS-Co M42 (8% Co)</td><td>Harder, more brittle</td><td>For production, not hand drilling</td></tr><tr><td>Solid carbide</td><td>Works, but shatters if you lever it</td><td>Only in a drill press</td></tr></table><p><b>Speeds that work:</b> 6 mm bit, about 600 rpm in 304; 10 mm, about 350 rpm. Use a centre punch, keep the pressure steady, and never let the bit spin without cutting — that is what work-hardens stainless.</p>', 'answer_short': 'Use M35 cobalt with a 135-degree split point, cutting fluid, and about a third of mild-steel rpm. Letting the bit rub instead of cut is what destroys stainless.', 'links': ['DB-13M', 'DB-51C']},
 {'slug': 'drill-bit-for-hardwood', 'q': 'Best drill bit for hardwood?', 'a': 'Brad-point for clean holes with a precise entry, auger for deep holes, Forstner for flat bottoms. Standard twist bits wander on hardwood.', 'body': '<table><tr><th>Bit</th><th>Best for</th><th>Note</th></tr><tr><td>Brad-point</td><td>Clean entry, precise location</td><td>Not for metal</td></tr><tr><td>Auger</td><td>Deep holes, fast chip clearing</td><td>Needs a lead screw start</td></tr><tr><td>Forstner</td><td>Flat-bottomed, large diameter</td><td>Slow, clean</td></tr><tr><td>Twist (HSS)</td><td>Wood with nails risk</td><td>Wanders unless centre-punched</td></tr></table><p><b>Hardwood specifics:</b> back the piece with scrap to stop blowout, and clear chips often — hardwood chips pack and heat the bit.</p>', 'answer_short': 'Brad-point for clean precise entry, auger for deep holes, Forstner for flat bottoms. Plain twist bits wander on hardwood.', 'links': ['DB-21M', 'DB-13M']},
 {'slug': 'drill-bit-for-tile', 'q': 'How do you drill a hole in tile without cracking it?', 'a': 'Carbide-tipped masonry bit at low rpm with no hammer action, or a diamond hole saw with water. Never use hammer mode on tile.', 'body': '<table><tr><th>Tool</th><th>Use</th><th>Risk</th></tr><tr><td>Carbide masonry bit</td><td>Small holes, soft tile</td><td>Cracks glaze if hammered</td></tr><tr><td>Diamond hole saw + water</td><td>Any size, porcelain</td><td>Slow, needs cooling</td></tr><tr><td>Glass and tile bit</td><td>Wall tile, under 10 mm</td><td>Wears out fast</td></tr></table><p><b>Sequence that works:</b> masking tape over the spot, start at 45 degrees to break the glaze, straighten up, low rpm, no hammer, water if porcelain. Porcelain is much harder than ceramic — expect ten minutes a hole.</p>', 'answer_short': 'Carbide masonry bit at low rpm with hammer off, or a diamond hole saw with water. Hammer mode is what cracks tile.', 'links': ['HS-8']},
 {'slug': 'screw-extractor-how-to', 'q': 'How do I get out a stripped screw?', 'a': 'Drill a pilot in the head, use a left-hand extractor, turn counter-clockwise with steady pressure. Heat helps if there is threadlocker.', 'body': '<table><tr><th>Situation</th><th>Method</th></tr><tr><td>Head stripped, screw proud</td><td>Cut a slot with a Dremel, use a flathead</td></tr><tr><td>Head stripped, flush</td><td>Pilot hole, extractor bit</td></tr><tr><td>Snapped below surface</td><td>Left-hand drill bit, then extractor</td></tr><tr><td>Threadlocked</td><td>Heat to 200 C, then extract</td></tr><tr><td>In hardwood</td><td>Hollow around it with a plug cutter, glue a plug back</td></tr></table><p><b>Do not:</b> use a bigger screwdriver and force it. That shears the head and makes the job twice as hard.</p>', 'answer_short': 'Drill a pilot into the head, use a left-hand extractor turning counter-clockwise with steady pressure. Heat first if threadlocker was used.', 'links': ['DB-13M']},
 {'slug': 'tap-and-die-for-stripped-threads', 'q': 'Can a tap and die set repair stripped threads?', 'a': 'For internal threads, yes if there is enough material left — use the same size tap to clean up, or go oversize and fit an insert. For external threads, a die can usually be run back over.', 'body': '<table><tr><th>Damage</th><th>Repair</th></tr><tr><td>Internal thread burred</td><td>Run the correct tap through to clean</td></tr><tr><td>Internal thread torn out</td><td>Drill oversize, fit a thread insert</td></tr><tr><td>External thread burred</td><td>Run a die over it</td></tr><tr><td>External thread stripped</td><td>Cut down one size, or weld and re-cut</td></tr></table><p><b>Insert kits are the real fix</b> for torn-out threads in aluminium and cast iron. A tap set cleans and cuts; it cannot add metal back.</p>', 'answer_short': 'Yes for burred threads — run the correct tap or die through to clean them. For torn-out threads you need a thread insert, since a tap cannot add material back.', 'links': ['TD-40', 'TD-40B']},
 {'slug': 'thread-pitch-gauge-how-to-use', 'q': 'How do I measure thread pitch without a gauge?', 'a': 'Measure across ten threads and divide by ten, or match against a known bolt. Pitch is the distance between crests, not the diameter.', 'body': '<table><tr><th>Method</th><th>How</th><th>Accuracy</th></tr><tr><td>Ten-thread rule</td><td>Measure 10 pitches with a caliper, divide by 10</td><td>Good enough to buy a tap</td></tr><tr><td>Thread gauge</td><td>Try leaves until one fits the crests</td><td>Exact</td></tr><tr><td>Match a known bolt</td><td>Interlock threads with a known fastener</td><td>Exact if the known one is right</td></tr></table><p><b>Metric vs imperial:</b> M8 x 1.25 means 8 mm diameter, 1.25 mm pitch. 5/16-18 means 5/16 in diameter, 18 threads per inch. Mixing the two is the most common buying mistake.</p>', 'answer_short': 'Measure across ten threads with a caliper and divide by ten, or interlock threads with a known bolt. Pitch is crest-to-crest distance, not diameter.', 'links': ['TD-40B', 'TD-40T']},
 {'slug': 'hand-tap-vs-machine-tap', 'q': 'Hand tap or machine tap?', 'a': 'Hand taps come in taper, plug and bottoming sets and are meant to be turned by hand with a wrench. Machine taps cut in one pass in a machine, and snap if used by hand.', 'body': '<table><tr><th></th><th>Hand tap (set of 3)</th><th>Machine tap</th></tr><tr><td>Passes</td><td>Taper, plug, bottoming</td><td>One</td></tr><tr><td>Use</td><td>By hand, in place</td><td>Drill press or CNC</td></tr><tr><td>Chip evacuation</td><td>Forward, needs backing out</td><td>Spiral flute, pulls chips back</td></tr><tr><td>Breaks if</td><td>Side load or no fluid</td><td>Used by hand, uneven torque</td></tr></table><p><b>For repair work on the bench:</b> a taper-plug-bottoming set with a tap wrench is what you want. For production, a spiral-flute machine tap.</p>', 'answer_short': 'Hand taps are a three-piece set turned with a wrench. Machine taps cut in one pass and break if turned by hand. Use hand taps for repair, machine taps in a spindle.', 'links': ['TD-40', 'TD-40T']},
 {'slug': 'die-stock-vs-die-wrench', 'q': 'Die stock or die wrench — which one do I need?', 'a': 'A die stock holds round split dies for cutting external threads. A die wrench (or die handle) is the older two-handle version. Both do the same job; the stock is easier to keep square.', 'body': '<table><tr><th></th><th>Die stock</th><th>Die wrench</th></tr><tr><td>Die type</td><td>Round split dies</td><td>Round or hex dies</td></tr><tr><td>Squareness</td><td>Easier to start square</td><td>Needs care</td></tr><tr><td>Common in sets</td><td>Yes</td><td>Older sets</td></tr></table><p><b>Starting square is everything:</b> a die that starts crooked cuts an undersized, tapered thread that will not hold torque. Chamfer the rod end first, and turn back a quarter turn every half turn to break the chip.</p>', 'answer_short': 'Both hold the die and cut external threads; a die stock keeps the die squarer at the start, which is what determines whether the thread holds torque.', 'links': ['TD-40', 'TD-40B']},
 {'slug': 'carbide-burr-for-aluminum', 'q': 'Which carbide burr for aluminium?', 'a': 'Single cut with a coarse tooth, run slower than you would in steel, with a wax or oil lubricant to stop the aluminium welding to the flutes.', 'body': '<table><tr><th>Cut</th><th>In aluminium</th><th>Result</th></tr><tr><td>Single (aluminium cut)</td><td>Best</td><td>Clears chips, less loading</td></tr><tr><td>Double</td><td>Works</td><td>Finer finish, loads faster</td></tr><tr><td>Diamond cut</td><td>Poor</td><td>Clogs immediately</td></tr></table><p><b>Speed:</b> about half the rpm you would use in steel. Aluminium melts onto a hot flute and then the burr cuts nothing. A stick of burr lubricant is not optional.</p>', 'answer_short': 'Single cut, coarse tooth, run at roughly half steel rpm with wax lubricant. Aluminium welds onto a hot flute and then the burr stops cutting.', 'links': ['CB-10S', 'CB-10D']},
 {'slug': 'burr-speed-chart', 'q': 'What rpm should I run a carbide burr at?', 'a': 'It depends on head diameter and material. A 6 mm head runs about 25,000 rpm in aluminium and 12,000 in stainless. Bigger head, slower.', 'body': '<table><tr><th>Head dia</th><th>Aluminium</th><th>Steel</th><th>Stainless</th></tr><tr><td>3 mm</td><td>35,000</td><td>20,000</td><td>15,000</td></tr><tr><td>6 mm</td><td>25,000</td><td>14,000</td><td>10,000</td></tr><tr><td>10 mm</td><td>16,000</td><td>9,000</td><td>6,000</td></tr><tr><td>12 mm</td><td>13,000</td><td>7,500</td><td>5,000</td></tr></table><p><b>Signs you are too fast:</b> blue discolouration, the burr bouncing, chips turning to dust. Signs you are too slow: chatter and a rough finish. Always run a test pass on scrap.</p>', 'answer_short': 'Six mm head: about 25,000 rpm in aluminium, 14,000 in steel, 10,000 in stainless. Larger heads run proportionally slower.', 'links': ['CB-10D', 'CB-10S']},
 {'slug': 'cnc-feed-and-speed-for-wood', 'q': 'What feed and speed should I use for CNC cutting wood?', 'a': 'Start at 18,000 rpm with a 6 mm bit, 2,000-3,000 mm/min feed, 3 mm depth of cut. Then adjust by chip size, not by sound.', 'body': '<table><tr><th>Material</th><th>RPM</th><th>Feed (6 mm bit)</th><th>Depth</th></tr><tr><td>Softwood</td><td>16,000-18,000</td><td>3,000-4,000 mm/min</td><td>4-6 mm</td></tr><tr><td>Hardwood</td><td>18,000</td><td>2,000-3,000 mm/min</td><td>3-4 mm</td></tr><tr><td>MDF</td><td>18,000-20,000</td><td>3,000-5,000 mm/min</td><td>4-6 mm</td></tr><tr><td>Plywood</td><td>18,000</td><td>2,500-3,500 mm/min</td><td>3-4 mm</td></tr></table><p><b>Read the chips:</b> fine dust means you are too slow or the bit is dull; long curly chips mean you are close; burned edges mean too slow a feed for the rpm.</p>', 'answer_short': 'Rough starting point for a 6 mm bit: 18,000 rpm, 2,000-3,000 mm/min, 3 mm depth of cut, then adjust by chip size. Dust means too slow, burns mean the feed is too light.', 'links': ['RB-12Z', 'RB-15Z']},
 {'slug': 'router-bit-bearing-replacement', 'q': 'Can I replace a worn bearing on a router bit?', 'a': 'Yes on most bits with a bearing. The bearing is a standard size; measure the bore and the outer diameter and buy a sealed replacement.', 'body': '<table><tr><th>Measure</th><th>Example</th></tr><tr><td>Inner bore</td><td>4 mm or 5 mm</td></tr><tr><td>Outer diameter</td><td>12 mm, 16 mm, 22 mm</td></tr><tr><td>Width</td><td>4 mm, 5 mm</td></tr><tr><td>Type</td><td>Sealed, not shielded, for dust</td></tr></table><p><b>Removing it:</b> the bearing is held by a screw or a circlip. Hold the bit by the shank in a soft jaw, never in a vice on the flutes. If the bearing race is scored, the bit was run without cleaning — fix the habit, not just the bearing.</p>', 'answer_short': 'Yes. Measure the bore, outer diameter and width and fit a sealed bearing. A scored race means the bit was run without cleaning.', 'links': ['RB-12W', 'RB-15HW']},
 {'slug': 'right-angle-drill-adapter', 'q': 'Do right-angle drill adapters work?', 'a': 'For light work in tight spaces, yes. They cannot take the torque of a hole saw or a large bit, and the cheap ones strip their gears quickly.', 'body': '<table><tr><th>Use</th><th>Verdict</th></tr><tr><td>Driving screws in a corner</td><td>Works</td></tr><tr><td>Small holes under 8 mm</td><td>Works</td></tr><tr><td>Hole saw</td><td>Do not</td></tr><tr><td>Auger or spade bit</td><td>Do not</td></tr></table><p><b>Alternative that always works:</b> a short stub drill bit plus a compact chuck gets into most tight spots without an adapter at all.</p>', 'answer_short': 'For screws and small holes in tight spaces, yes. They cannot handle a hole saw or a large bit — the gears strip.', 'links': ['DB-13M']},
 {'slug': 'cordless-drill-chuck-and-bit-size', 'q': 'What size bits fit a 3/8 in chuck?', 'a': 'Round or hex shanks up to 10 mm (3/8 in). A 1/2 in chuck takes up to 13 mm. Hex shanks up to 1/4 in fit both.', 'body': "<table><tr><th>Chuck</th><th>Max round shank</th><th>Hex shank</th></tr><tr><td>3/8 in (10 mm)</td><td>10 mm</td><td>1/4 in hex</td></tr><tr><td>1/2 in (13 mm)</td><td>13 mm</td><td>1/4 in and 5/16 in hex</td></tr><tr><td>1/4 in hex driver</td><td>None</td><td>1/4 in hex only</td></tr></table><p><b>Common mistake:</b> buying a 1/2 in shank router bit or a large hole saw arbor for a 3/8 in drill. Check the shank, not the drill's power rating.</p>", 'answer_short': 'A 3/8 in chuck takes round shanks up to 10 mm; a 1/2 in chuck up to 13 mm. Hex shanks up to 1/4 in fit both.', 'links': ['DB-13M', 'DB-21M']},
]
